INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(700, 'conflict', '/ˈkɒnflɪkt/', 'noun', '{"zh-TW":["衝突；矛盾"],"en":["a serious disagreement or argument","a serious disagreement","a prolonged struggle"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"flict","meaning":"strike (打擊)"},"logic":"一起打擊碰撞，即「衝突」。"}', 'conflict of interest / resolve a conflict; conflict of interest / armed conflict / resolve a conflict', '[{"en":"There is a conflict of interest in this situation.","zh-TW":"在這種情況下存在利益衝突。"},{"en":"The manager helped resolve the conflict between teams.","zh-TW":"經理幫助解決了團隊之間的衝突。"},{"en":"There is a conflict between the two departments.","zh-TW":"兩個部門之間有衝突。"},{"en":"The conflict lasted for several years.","zh-TW":"衝突持續了好幾年。"}]', '{"adjective":"conflicting","verb":"conflict"}', NULL, 3, 700, NULL),
(701, 'conform', '/kənˈfɔːrm/', 'verb', '{"zh-TW":["符合；遵從"],"en":["to comply with rules, standards, or conventions"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"form","meaning":"shape (形狀)"},"logic":"完全成為相同形狀，即「符合」。"}', 'conform to standards/regulations/expectations', '[{"en":"All products must conform to industry standards.","zh-TW":"所有產品必須符合行業標準。"},{"en":"The design conforms to local building regulations.","zh-TW":"設計符合當地建築法規。"}]', '{"noun":"conformity"}', NULL, 3, 701, NULL),
(702, 'confront', '/kənˈfrʌnt/', 'verb', '{"zh-TW":["面對；對抗"],"en":["to face a difficult situation or person"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"front","meaning":"face/forehead (面)"},"logic":"完全面對面，即「面對」。"}', 'confront a challenge/problem/issue', '[{"en":"Companies must confront the challenge of digital transformation.","zh-TW":"企業必須面對數位轉型的挑戰。"},{"en":"The CEO confronted the issue directly at the meeting.","zh-TW":"執行長在會議上直接面對了這個問題。"}]', '{"noun":"confrontation"}', NULL, 3, 702, NULL),
(703, 'conglomerate', '/kənˈɡlɒmərɪt/', 'noun', '{"zh-TW":["企業集團；綜合企業"],"en":["a large corporation made up of different businesses"]}', NULL, 'multinational conglomerate / media conglomerate', '[{"en":"The company grew into a multinational conglomerate.","zh-TW":"公司發展成為跨國企業集團。"},{"en":"The media conglomerate owns several TV stations.","zh-TW":"這家媒體集團擁有多個電視台。"}]', '{"noun":"conglomerate","noun2":"conglomeration"}', NULL, 4, 703, NULL),
(704, 'congress', '/ˈkɒŋɡrɛs/', 'noun', '{"zh-TW":["國會"],"en":["the national legislative body"]}', NULL, 'member of congress / congressional hearing', '[{"en":"Congress passed the new law.","zh-TW":"國會通過了新法律。"},{"en":"She was elected to Congress.","zh-TW":"她被選入了國會。"}]', '{"adjective":"congressional"}', NULL, 3, 704, NULL),
(705, 'connect', 'kəˈnɛkt', 'verb', '{"zh-TW":["連接；聯繫","關聯"],"en":["to join together","to establish contact"]}', NULL, 'connect with clients/connect systems', '[{"en":"Let me connect you with the right department.","zh-TW":"讓我為您接通正確的部門。"}]', '{"noun":"connection","adjective":"connected","adverb":"connectedly"}', NULL, 3, 705, NULL),
(706, 'connection', '/kəˈnɛkʃən/', 'noun', '{"zh-TW":["連接；關聯"],"en":["a link between things or people"]}', NULL, 'internet connection / personal connection', '[{"en":"I have a poor internet connection.","zh-TW":"我的網路連線很差。"},{"en":"There''s a connection between diet and health.","zh-TW":"飲食和健康之間有關聯。"}]', '{"verb":"connect","adjective":"connected"}', NULL, 4, 706, NULL),
(707, 'conscious', '/ˈkɒnʃəs/', 'adjective', '{"zh-TW":["有意識的；自覺的"],"en":["aware of and responding to surroundings","aware of and responding to one''s surroundings"]}', '{"prefix":{"text":"con-","meaning":"with (帶有)"},"root":{"text":"sci","meaning":"know (知道)"},"suffix":{"text":"-ous","meaning":"having (具有)"},"logic":"帶有知覺的，即「有意識的」。"}', 'conscious effort / self-conscious; conscious effort / conscious decision / self-conscious', '[{"en":"She made a conscious effort to be kind.","zh-TW":"她有意識地努力做到友善。"},{"en":"He was barely conscious after the accident.","zh-TW":"事故後他幾乎失去意識。"},{"en":"She made a conscious effort to be polite.","zh-TW":"她有意識地努力保持禮貌。"},{"en":"He was barely conscious after the accident.","zh-TW":"事故後他幾乎沒有意識了。"}]', '{"noun":"consciousness","adverb":"consciously"}', NULL, 3, 707, NULL),
(708, 'consecutive', '/kənˈsekjʊtɪv/', 'adjective', '{"zh-TW":["連續的"],"en":["following each other without interruption"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"secut","meaning":"follow (跟隨)"},"suffix":{"text":"-ive","meaning":"having quality (具有特質)"},"logic":"一起跟隨的，即「連續的」。"}', 'consecutive years/months/quarters', '[{"en":"Revenue has grown for five consecutive quarters.","zh-TW":"營收已連續五個季度成長。"},{"en":"She won the award for three consecutive years.","zh-TW":"她連續三年獲得該獎項。"}]', '{"adverb":"consecutively"}', NULL, 4, 708, NULL),
(709, 'consensus', '/kənˈsɛnsəs/', 'noun', '{"zh-TW":["共識；一致意見"],"en":["general agreement among a group"]}', NULL, 'reach a consensus / build consensus', '[{"en":"The team reached a consensus on the new strategy.","zh-TW":"團隊就新策略達成了共識。"},{"en":"Building consensus takes time but leads to better outcomes.","zh-TW":"建立共識需要時間，但會帶來更好的結果。"}]', '{"adjective":"consensual"}', NULL, 3, 709, NULL),
(710, 'consent', '/kənˈsent/', 'noun', '{"zh-TW":["同意；許可"],"en":["permission or agreement to do something"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sent","meaning":"feel (感覺)"},"logic":"一起有相同感覺，即「同意」。"}', 'give consent / informed consent / without consent', '[{"en":"Written consent is required before processing personal data.","zh-TW":"處理個人資料前需要書面同意。"},{"en":"The change was made without employee consent.","zh-TW":"變更未經員工同意就進行了。"}]', NULL, NULL, 3, 710, NULL),
(711, 'consequence', '/ˈkɒnsɪkwəns/', 'noun', '{"zh-TW":["後果；結果"],"en":["a result or effect of an action or condition"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"sequ","meaning":"follow (跟隨)"},"suffix":{"text":"-ence","meaning":"state (狀態)"},"logic":"完全跟隨而來的，即「後果」。"}', 'as a consequence / face consequences / serious consequences', '[{"en":"As a consequence of the delay, costs increased significantly.","zh-TW":"由於延遲，成本大幅增加。"},{"en":"Failure to comply will have serious consequences.","zh-TW":"不遵守將會有嚴重後果。"}]', '{"adjective":"consequent","adverb":"consequently"}', NULL, 4, 711, NULL),
(712, 'conservation', '/ˌkɒnsərˈveɪʃn/', 'noun', '{"zh-TW":["保育；保存"],"en":["the protection of natural resources"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"serv","meaning":"keep (保存)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"共同保存的過程，即「保育」。"}', 'wildlife conservation / energy conservation', '[{"en":"Wildlife conservation is critical for biodiversity.","zh-TW":"野生動物保育對生物多樣性至關重要。"},{"en":"Energy conservation reduces electricity bills.","zh-TW":"節約能源可以減少電費。"}]', '{"verb":"conserve","adjective":"conservative","noun2":"conservationist"}', NULL, 4, 712, NULL),
(713, 'conservative', '/kənˈsɜːrvətɪv/', 'adjective', '{"zh-TW":["保守的；謹慎的"],"en":["averse to change; cautious in estimate"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"serv","meaning":"keep (保持)"},"suffix":{"text":"-ative","meaning":"tending to (傾向)"},"logic":"傾向完全保持的，即「保守的」。"}', 'conservative estimate / conservative approach', '[{"en":"A conservative estimate puts the cost at $3 million.","zh-TW":"保守估計成本為300萬美元。"},{"en":"The company took a conservative approach to investing.","zh-TW":"公司採取保守的投資策略。"}]', NULL, NULL, 4, 713, NULL),
(714, 'consider', '/kənˈsɪdər/', 'verb', '{"zh-TW":["考慮；認為"],"en":["to think carefully about something"]}', NULL, 'consider doing / all things considered', '[{"en":"Please consider my proposal.","zh-TW":"請考慮我的提案。"},{"en":"She is considered an expert.","zh-TW":"她被認為是專家。"}]', '{"noun":"consideration","adjective":"considerable"}', NULL, 3, 714, NULL),
(715, 'considerable', '/kənˈsɪdərəbl/', 'adjective', '{"zh-TW":["相當大的；可觀的"],"en":["notably large in size, amount, or extent"]}', '{"prefix":{"text":"con-","meaning":"fully (完全)"},"root":{"text":"sider","meaning":"star (星)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠完全被考量的（重要的），即「相當大的」。"}', 'considerable amount/effort/experience', '[{"en":"The project requires considerable investment.","zh-TW":"該專案需要大量投資。"},{"en":"She has considerable experience in marketing.","zh-TW":"她在行銷方面有豐富的經驗。"}]', '{"adverb":"considerably"}', NULL, 4, 715, NULL),
(716, 'considerate', '/kənˈsɪdərət/', 'adjective', '{"zh-TW":["體貼的；考慮周到的"],"en":["careful not to inconvenience or harm others"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sider","meaning":"star (星)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"如同觀星般仔細考量他人，即「體貼的」。"}', 'considerate of others / thoughtful and considerate', '[{"en":"He is always considerate of other people''s feelings.","zh-TW":"他總是顧及他人的感受。"},{"en":"It was considerate of you to call first.","zh-TW":"你先打電話來很體貼。"}]', '{"noun":"consideration","verb":"consider"}', NULL, 4, 716, NULL),
(717, 'consideration', '/kənˌsɪdəˈreɪʃən/', 'noun', '{"zh-TW":["對價；報酬"],"en":["something of value exchanged between contracting parties"]}', NULL, 'valuable consideration / in consideration of', '[{"en":"The contract must include a valid consideration to be enforceable.","zh-TW":"合約必須包含有效的對價才能執行。"},{"en":"In consideration of payment, the service will begin immediately.","zh-TW":"作為付款的對價，服務將立即開始。"}]', '{"verb":"consider","adjective":"considerable"}', NULL, 5, 717, NULL),
(718, 'consignee', '/ˌkɒnsɪˈniː/', 'noun', '{"zh-TW":["收貨人"],"en":["the person or company to whom goods are shipped or delivered"]}', NULL, 'notify the consignee / consignee address', '[{"en":"The consignee must present the bill of lading to collect the cargo.","zh-TW":"收貨人必須提交提單才能提取貨物。"},{"en":"All shipping documents must clearly identify the consignee.","zh-TW":"所有運輸文件必須清楚地標明收貨人。"}]', '{"opposite":"consignor"}', NULL, 3, 718, NULL),
(719, 'consignment', '/kənˈsaɪnmənt/', 'noun', '{"zh-TW":["托運；一批貨物"],"en":["a batch of goods sent or delivered"]}', NULL, 'receive a consignment / consignment note', '[{"en":"A consignment of electronics arrived from the factory.","zh-TW":"一批電子產品從工廠運到了。"},{"en":"The consignment will be delivered within five business days.","zh-TW":"這批貨物將在五個工作日內送達。"}]', '{"verb":"consign","noun":"consignee"}', NULL, 4, 719, NULL),
(720, 'consist', '/kənˈsɪst/', 'verb', '{"zh-TW":["由…組成"],"en":["to be composed or made up of"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sist","meaning":"stand (站)"},"logic":"一起站立的，即「組成」。"}', 'consist of / consist in', '[{"en":"The team consists of 15 experienced professionals.","zh-TW":"團隊由15位經驗豐富的專業人士組成。"},{"en":"The test consists of three sections.","zh-TW":"測驗由三個部分組成。"}]', '{"adjective":"consistent","noun":"consistency"}', NULL, 3, 720, NULL),
(721, 'consistent', '/kənˈsɪstənt/', 'adjective', '{"zh-TW":["一致的；持續的"],"en":["unchanging over time; compatible"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sist","meaning":"stand (站立)"},"suffix":{"text":"-ent","meaning":"being (…的)"},"logic":"站在一起不變的，即「一致的」。"}', 'consistent results / consistent with / remain consistent', '[{"en":"She has been consistent in her performance.","zh-TW":"她的表現一直很穩定。"},{"en":"The data is consistent with our hypothesis.","zh-TW":"數據與我們的假設一致。"}]', '{"noun":"consistency","adverb":"consistently"}', NULL, 4, 721, 962),
(722, 'consolidate', '/kənˈsɒlɪdeɪt/', 'verb', '{"zh-TW":["合併；鞏固"],"en":["to combine into a single more effective whole","to strengthen a position"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"solid","meaning":"solid (堅固)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使一起堅固，即「合併、鞏固」。"}', 'consolidate operations/position/power', '[{"en":"The company consolidated its three offices into one.","zh-TW":"公司將三個辦公室合併為一個。"},{"en":"We aim to consolidate our market position.","zh-TW":"我們旨在鞏固市場地位。"}]', '{"noun":"consolidation"}', NULL, 4, 722, 659),
(723, 'consolidation', '/kənˌsɒlɪˈdeɪʃən/', 'noun', '{"zh-TW":["整合；鞏固"],"en":["the merging of multiple businesses or operations into one"]}', NULL, 'industry consolidation / debt consolidation', '[{"en":"Industry consolidation has reduced competition.","zh-TW":"行業整合降低了競爭程度。"},{"en":"The consolidation of the two divisions improved efficiency.","zh-TW":"兩個部門的整合提高了效率。"}]', '{"verb":"consolidate","adjective":"consolidated"}', NULL, 5, 723, 530),
(724, 'consortium', '/kənˈsɔːrtiəm/', 'noun', '{"zh-TW":["聯盟；財團"],"en":["a group of companies working together"]}', NULL, 'form a consortium / industry consortium', '[{"en":"Three firms formed a consortium for the bid.","zh-TW":"三家公司組成聯盟參與競標。"},{"en":"The consortium invested in infrastructure.","zh-TW":"財團投資了基礎設施。"}]', '{"noun":"consortium","plural":"consortia"}', NULL, 4, 724, 763),
(725, 'constant', '/ˈkɒnstənt/', 'adjective', '{"zh-TW":["不斷的；恆定的"],"en":["happening all the time without stopping"]}', NULL, 'constant pressure / constant speed', '[{"en":"The noise was constant.","zh-TW":"噪音持續不斷。"},{"en":"She''s under constant pressure.","zh-TW":"她承受著持續的壓力。"}]', '{"adverb":"constantly","noun":"constancy"}', NULL, 3, 725, NULL),
(726, 'constitute', '/ˈkɒnstɪtjuːt/', 'verb', '{"zh-TW":["構成；組成"],"en":["to be a part of a whole","to be equivalent to"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"stitut","meaning":"set up (建立)"},"logic":"一起建立起來的，即「構成」。"}', 'constitute a majority/threat/violation', '[{"en":"Foreign sales constitute 60% of total revenue.","zh-TW":"海外銷售構成總營收的60%。"},{"en":"This action may constitute a breach of contract.","zh-TW":"此行為可能構成違約。"}]', '{"noun":"constitution","adjective":"constitutional"}', NULL, 4, 726, 660),
(727, 'constitution', '/ˌkɒnstɪˈtjuːʃən/', 'noun', '{"zh-TW":["憲法"],"en":["the fundamental laws of a country"]}', NULL, 'written constitution / constitutional right', '[{"en":"The constitution guarantees basic rights.","zh-TW":"憲法保障基本權利。"},{"en":"It''s protected by the constitution.","zh-TW":"這受到憲法保護。"}]', '{"adjective":"constitutional"}', NULL, 4, 727, NULL),
(728, 'constraint', '/kənˈstreɪnt/', 'noun', '{"zh-TW":["限制；約束"],"en":["a limitation or restriction"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"strain","meaning":"bind/tighten (綁/拉緊)"},"suffix":{"text":"-t","meaning":"noun ending"},"logic":"完全綁緊的，即「限制」。"}', 'budget constraints / time constraints / within constraints', '[{"en":"Budget constraints limit what we can accomplish.","zh-TW":"預算限制了我們能完成的事。"},{"en":"We must work within these constraints.","zh-TW":"我們必須在這些限制內工作。"}]', '{"verb":"constrain"}', NULL, 4, 728, NULL),
(729, 'construct', '/kənˈstrʌkt/', 'verb', '{"zh-TW":["建造；構建"],"en":["to build or erect something"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"struct","meaning":"build (建造)"},"logic":"一起建造，即「建造」。"}', 'construct a building/argument/plan', '[{"en":"The new headquarters will be constructed next year.","zh-TW":"新總部將於明年建造。"},{"en":"The lawyer constructed a compelling argument.","zh-TW":"律師構建了一個有說服力的論點。"}]', '{"noun":"construction","adjective":"constructive"}', NULL, 3, 729, 733),
(730, 'construction', '/kənˈstrʌkʃən/', 'noun', '{"zh-TW":["建設；建造"],"en":["the process of building something"]}', NULL, 'under construction / construction site', '[{"en":"The building is under construction.","zh-TW":"大樓正在建設中。"},{"en":"Construction will be completed next year.","zh-TW":"建設將於明年完工。"}]', '{"verb":"construct","adjective":"constructive"}', NULL, 4, 730, 305),
(731, 'constructive', 'kənˈstrʌktɪv', 'adjective', '{"zh-TW":["建設性的；有益的","積極的"],"en":["intended to be helpful","positive and useful"]}', NULL, 'constructive feedback/constructive criticism', '[{"en":"Please provide constructive feedback.","zh-TW":"請提供建設性的反饋。"}]', '{"noun":"construction","adverb":"constructively"}', NULL, 4, 731, 963),
(732, 'consult', '/kənˈsʌlt/', 'verb', '{"zh-TW":["諮詢；查閱"],"en":["to seek information or advice from someone"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sult","meaning":"take counsel (取得建議)"},"logic":"一起取得建議，即「諮詢」。"}', 'consult with / consult a specialist', '[{"en":"You should consult a lawyer before signing.","zh-TW":"簽名前你應該諮詢律師。"},{"en":"The management consulted with employees on the change.","zh-TW":"管理層就變革與員工進行了諮詢。"}]', '{"noun":"consultant","noun2":"consultation"}', NULL, 3, 732, 90),
(733, 'consultant', '/kənˈsʌltənt/', 'noun', '{"zh-TW":["顧問；諮詢師"],"en":["an expert who provides professional advice to organizations"]}', NULL, 'management consultant / IT consultant / hire a consultant / outside consultant', '[{"en":"The company brought in a management consultant to review operations.","zh-TW":"公司聘請了管理顧問審查運營。"},{"en":"The consultant delivered recommendations within six weeks.","zh-TW":"顧問在六週內提供了建議。"}]', '{"plural":"consultants","verb":"consult","noun":"consultancy"}', NULL, 4, 733, NULL),
(734, 'consume', '/kənˈsjuːm/', 'verb', '{"zh-TW":["消費；消耗","消耗；消費"],"en":["to use up a resource","to eat or drink something","to use up; to eat or drink","to eat or drink"]}', '{"prefix":{"text":"con-","meaning":"completely (完全)"},"root":{"text":"sume","meaning":"take (拿取)"},"logic":"完全拿取用盡，即「消費」。"}', 'consume energy/resources/time; consume energy / consume food; consume energy / consume food / time-consuming', '[{"en":"The factory consumes large amounts of electricity.","zh-TW":"工廠消耗大量電力。"},{"en":"This process consumes too much time.","zh-TW":"這個流程消耗太多時間。"},{"en":"The factory consumes a lot of energy.","zh-TW":"工廠消耗大量能源。"},{"en":"Americans consume too much sugar.","zh-TW":"美國人攝取過多糖分。"},{"en":"Cars consume a lot of fuel.","zh-TW":"汽車消耗大量燃料。"},{"en":"Americans consume more sugar than recommended.","zh-TW":"美國人攝取的糖分超過建議量。"}]', '{"noun":"consumer","noun2":"consumption"}', NULL, 3, 734, 91),
(735, 'consumer', '/kənˈsjuːmər/', 'noun', '{"zh-TW":["消費者"],"en":["a person who purchases goods or services for personal use"]}', NULL, 'target consumer / consumer behavior', '[{"en":"Understanding consumer behavior is key to effective marketing.","zh-TW":"了解消費者行為是有效行銷的關鍵。"},{"en":"Consumer demand for eco-friendly products is growing.","zh-TW":"消費者對環保產品的需求不斷增長。"}]', '{"verb":"consume","noun2":"consumption","adjective":"consumer"}', NULL, 3, 735, 306),
(736, 'contact', '/ˈkɒntækt/', 'noun', '{"zh-TW":["聯繫；接觸","聯絡人"],"en":["communication with someone","a person who may be consulted"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tact","meaning":"touch (觸碰)"},"logic":"一起觸碰，即「聯繫」。"}', 'contact information / make contact / point of contact', '[{"en":"Please don''t hesitate to contact us for more details.","zh-TW":"如需更多詳情，請隨時與我們聯繫。"},{"en":"She is our primary point of contact for the project.","zh-TW":"她是我們這個專案的主要聯絡人。"}]', NULL, NULL, 3, 736, 18),
(737, 'contain', '/kənˈteɪn/', 'verb', '{"zh-TW":["包含；容納","控制"],"en":["to have within itself","to prevent from spreading","to have something inside"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tain","meaning":"hold (持有)"},"logic":"一起持有在內，即「包含」。"}', 'contain information / contain costs; contain information / self-contained', '[{"en":"The package contains fragile items.","zh-TW":"包裹內含易碎物品。"},{"en":"We must contain costs to maintain profitability.","zh-TW":"我們必須控制成本以維持獲利。"},{"en":"This box contains old photos.","zh-TW":"這個盒子裡有舊照片。"},{"en":"The drink contains no sugar.","zh-TW":"這飲料不含糖。"}]', '{"noun":"container","noun2":"content"}', NULL, 3, 737, 307),
(738, 'container', '/kənˈteɪnər/', 'noun', '{"zh-TW":["貨櫃；容器"],"en":["a large metal box for transporting goods by ship or truck"]}', NULL, 'shipping container / container ship', '[{"en":"The goods were packed into a 40-foot shipping container.","zh-TW":"貨物被裝入一個40英尺的貨運貨櫃中。"},{"en":"Container shipping is the backbone of international trade.","zh-TW":"貨櫃運輸是國際貿易的支柱。"}]', NULL, NULL, 3, 738, NULL),
(739, 'contamination', '/kənˌtæmɪˈneɪʃən/', 'noun', '{"zh-TW":["污染；污染物"],"en":["the presence of a harmful substance in an environment"]}', NULL, 'water contamination / soil contamination', '[{"en":"Water contamination from industrial waste is a serious problem.","zh-TW":"工業廢水污染是一個嚴重問題。"},{"en":"The contamination was detected early enough to prevent harm.","zh-TW":"污染被及時發現，避免了傷害。"}]', '{"verb":"contaminate","adjective":"contaminated"}', NULL, 5, 739, NULL),
(740, 'contemporary', '/kənˈtempərəri/', 'adjective', '{"zh-TW":["當代的；同時期的"],"en":["living or occurring at the same time","modern or current","belonging to the present time"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tempor","meaning":"time (時間)"},"suffix":{"text":"-ary","meaning":"relating to (有關的)"},"logic":"在同一時間的，即「當代的」。"}', 'contemporary art/design/issues; contemporary art / contemporary music', '[{"en":"The office features contemporary design elements.","zh-TW":"辦公室採用當代設計元素。"},{"en":"We must address contemporary business challenges.","zh-TW":"我們必須面對當代商業挑戰。"},{"en":"The gallery specializes in contemporary art.","zh-TW":"這家畫廊專營當代藝術。"},{"en":"She is one of the greatest contemporary writers.","zh-TW":"她是最偉大的當代作家之一。"}]', '{"noun":"contemporary"}', NULL, 4, 740, NULL),
(741, 'content', '/ˈkɒntent/', 'noun', '{"zh-TW":["內容；目錄"],"en":["the material dealt with in a speech, text, or work"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tent","meaning":"hold (持有)"},"logic":"被一起持有在內的，即「內容」。"}', 'content marketing / table of contents / digital content', '[{"en":"The website needs fresh content updated weekly.","zh-TW":"網站需要每週更新新鮮內容。"},{"en":"Refer to the table of contents for guidance.","zh-TW":"請參閱目錄以獲取指導。"}]', NULL, NULL, 3, 741, 308),
(742, 'contest', '/ˈkɒntest/', 'noun', '{"zh-TW":["比賽；競爭","質疑"],"en":["a competition","to dispute or challenge"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"test","meaning":"witness (見證)"},"logic":"一起見證對決，即「比賽」。"}', 'contest a claim / enter a contest', '[{"en":"The company decided to contest the lawsuit.","zh-TW":"公司決定對訴訟進行抗辯。"},{"en":"Employees can enter the innovation contest.","zh-TW":"員工可以參加創新比賽。"}]', '{"noun":"contestant"}', NULL, 3, 742, NULL),
(743, 'contestant', '/kənˈtɛstənt/', 'noun', '{"zh-TW":["參賽者"],"en":["a person who takes part in a competition"]}', NULL, 'reality show contestant / elimination of contestants', '[{"en":"The contestant answered correctly.","zh-TW":"參賽者答對了。"},{"en":"Fifty contestants entered the competition.","zh-TW":"五十位參賽者參加了比賽。"}]', '{"noun2":"contest"}', NULL, 4, 743, NULL),
(744, 'context', '/ˈkɒntekst/', 'noun', '{"zh-TW":["背景；上下文"],"en":["the circumstances that form the setting for an event"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"text","meaning":"weave (編織)"},"logic":"一起編織的環境，即「背景」。"}', 'in context / business context / cultural context', '[{"en":"The remarks must be understood in context.","zh-TW":"這些言論必須在上下文中理解。"},{"en":"In a business context, this term has a specific meaning.","zh-TW":"在商業背景下，這個術語有特定含義。"}]', '{"adjective":"contextual"}', NULL, 3, 744, NULL),
(745, 'contingency', '/kənˈtɪndʒənsi/', 'noun', '{"zh-TW":["應急措施；意外事件"],"en":["a future event that is possible but cannot be predicted","a possible future event that must be prepared for"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"ting","meaning":"touch (觸碰)"},"suffix":{"text":"-ency","meaning":"state (狀態)"},"logic":"可能觸碰到的事件狀態，即「意外事件」。"}', 'contingency plan / contingency fund', '[{"en":"We need a contingency plan in case of delays.","zh-TW":"我們需要一個應對延遲的應急計畫。"},{"en":"The budget includes a 10% contingency fund.","zh-TW":"預算包含10%的應急基金。"},{"en":"We need a contingency plan for supply disruptions.","zh-TW":"我們需要一個應對供應中斷的應急計畫。"},{"en":"Set aside a contingency fund.","zh-TW":"設置一筆應急基金。"}]', '{"adjective":"contingent","noun":"contingency"}', NULL, 4, 745, 764),
(746, 'continue', '/kənˈtɪnjuː/', 'verb', '{"zh-TW":["繼續"],"en":["to keep going; not stop","to keep doing something without stopping"]}', NULL, 'continue to grow / continue with; continue to / continue with', '[{"en":"Sales continue to grow each quarter.","zh-TW":"銷售額每季持續成長。"},{"en":"Let''s continue with the presentation.","zh-TW":"讓我們繼續報告。"},{"en":"Please continue reading.","zh-TW":"請繼續閱讀。"},{"en":"The rain continued all day.","zh-TW":"雨下了一整天。"}]', '{"verb":"continue","adjective":"continuous","adverb":"continuously","noun":"continuation"}', NULL, 3, 746, 309),
(747, 'contract', '/ˈkɒntrækt/', 'noun', '{"zh-TW":["合約；契約"],"en":["a written or spoken agreement that is legally binding"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tract","meaning":"draw (拉)"},"logic":"一起拉在一起的約定，即「合約」。"}', 'sign a contract / breach of contract / contract terms', '[{"en":"Both parties signed the contract last week.","zh-TW":"雙方上週簽署了合約。"},{"en":"The contract expires at the end of this year.","zh-TW":"合約於今年年底到期。"}]', '{"noun":"contractor","adjective":"contractual"}', NULL, 3, 747, 19),
(748, 'contractor', 'ˈkɒntræktər', 'noun', '{"zh-TW":["承包商；合約工","包商"],"en":["a person hired on contract","a company hired for specific work"]}', NULL, 'hire a contractor/independent contractor', '[{"en":"We work with specialized contractors.","zh-TW":"我們與專業承包商合作。"}]', '{"noun":"contract","adjective":"contracted"}', NULL, 4, 748, 310),
(749, 'contribute', '/kənˈtrɪbjuːt/', 'verb', '{"zh-TW":["貢獻；捐助"],"en":["to give something to help achieve a common goal"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tribute","meaning":"give (給予)"},"logic":"一起給予，即「貢獻」。"}', 'contribute to / contribute funds/ideas', '[{"en":"Each team member contributed ideas to the project.","zh-TW":"每位團隊成員都為專案貢獻了想法。"},{"en":"Tourism contributes significantly to the local economy.","zh-TW":"旅遊業對當地經濟有重大貢獻。"}]', '{"noun":"contribution","noun2":"contributor"}', NULL, 4, 749, 92);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(750, 'contribution', 'ˌkɒntrɪˈbjuːʃən', 'noun', '{"zh-TW":["貢獻；捐助","投入"],"en":["something given to help","a donation or effort"]}', NULL, 'valuable contribution/financial contribution', '[{"en":"Thank you for your valuable contributions.","zh-TW":"感謝您寶貴的貢獻。"}]', '{"verb":"contribute","adjective":"contributing"}', NULL, 4, 750, 532),
(751, 'control', '/kənˈtroʊl/', 'noun', '{"zh-TW":["控制；管理"],"en":["the power to direct","to manage or regulate"]}', NULL, 'quality control / under control', '[{"en":"Quality control is essential in manufacturing.","zh-TW":"品質管理在製造業中至關重要。"},{"en":"The situation is under control.","zh-TW":"情況在掌控之中。"}]', '{"noun":"control","verb":"control","adjective":"controllable","noun2":"controller"}', NULL, 3, 751, NULL),
(752, 'controller', '/kənˈtroʊlər/', 'noun', '{"zh-TW":["財務總監；主計長"],"en":["the chief accounting officer responsible for financial reporting"]}', NULL, 'financial controller / appoint a controller / role of controller', '[{"en":"The controller oversees the company''s financial reporting process.","zh-TW":"財務總監監督公司的財務報告流程。"},{"en":"She was promoted to controller after ten years in the finance department.","zh-TW":"她在財務部門工作了十年後晉升為財務總監。"}]', '{"plural":"controllers"}', NULL, 4, 752, NULL),
(753, 'controversial', '/ˌkɒntrəˈvɜːrʃl/', 'adjective', '{"zh-TW":["有爭議的"],"en":["causing disagreement or discussion"]}', '{"prefix":{"text":"contra-","meaning":"against (對立)"},"root":{"text":"vers","meaning":"turn (轉向)"},"suffix":{"text":"-ial","meaning":"relating to (有關的)"},"logic":"朝對立方向轉的，即「有爭議的」。"}', 'controversial decision/issue/topic', '[{"en":"The board made a controversial decision to outsource.","zh-TW":"董事會做出了有爭議的外包決定。"},{"en":"The policy remains highly controversial.","zh-TW":"該政策仍然極具爭議。"}]', '{"noun":"controversy"}', NULL, 5, 753, NULL),
(754, 'controversy', '/ˈkɒntrəvɜːrsi/', 'noun', '{"zh-TW":["爭議"],"en":["prolonged public disagreement"]}', '{"prefix":{"text":"contra-","meaning":"against (反對)"},"root":{"text":"vers","meaning":"turn (轉)"},"suffix":{"text":"-y","meaning":"state (狀態)"},"logic":"反向轉動的狀態，即「爭議」。"}', 'cause controversy / political controversy', '[{"en":"The decision caused a lot of controversy.","zh-TW":"這個決定引起了很多爭議。"},{"en":"The new law has been surrounded by controversy.","zh-TW":"新法律一直充滿爭議。"}]', '{"adjective":"controversial"}', NULL, 4, 754, NULL),
(755, 'convene', '/kənˈviːn/', 'verb', '{"zh-TW":["召集；集合"],"en":["to bring together or call a meeting of a group"]}', NULL, 'convene a meeting / convene a committee', '[{"en":"The board will convene an emergency meeting to address the crisis.","zh-TW":"董事會將召集緊急會議應對危機。"},{"en":"The annual summit convened experts from 30 countries.","zh-TW":"年度峰會召集了來自30個國家的專家。"}]', '{"noun":"convention","adjective":"convened"}', NULL, 3, 755, 661),
(756, 'convenience', 'kənˈviːniəns', 'noun', '{"zh-TW":["方便；便利","舒適"],"en":["being easy to do or reach","a time that suits you"]}', NULL, 'at your convenience/for convenience', '[{"en":"Please call at your convenience.","zh-TW":"請在您方便的時候致電。"}]', '{"adjective":"convenient","adverb":"conveniently"}', NULL, 4, 756, NULL),
(757, 'convenient', '/kənˈviːniənt/', 'adjective', '{"zh-TW":["方便的；便利的"],"en":["fitting in well with needs or plans; easy to use"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"ven","meaning":"come (來)"},"suffix":{"text":"-ient","meaning":"being (存在的)"},"logic":"一起來到適合的地方，即「方便的」。"}', 'convenient location/time / at your convenience', '[{"en":"Please call us at your earliest convenience.","zh-TW":"請在您方便時盡早致電。"},{"en":"The office is in a convenient downtown location.","zh-TW":"辦公室位於便利的市中心位置。"}]', '{"noun":"convenience","adverb":"conveniently"}', NULL, 4, 757, 20),
(758, 'convention', '/kənˈvenʃn/', 'noun', '{"zh-TW":["大會；慣例"],"en":["a large meeting or conference","a widely accepted practice"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"ven","meaning":"come (來)"},"suffix":{"text":"-tion","meaning":"action (動作)"},"logic":"一起來的行動，即「大會」。"}', 'convention center / industry convention / by convention', '[{"en":"The annual convention attracted 3,000 attendees.","zh-TW":"年度大會吸引了3,000位出席者。"},{"en":"By convention, the report is submitted quarterly.","zh-TW":"按照慣例，報告每季提交。"}]', '{"adjective":"conventional"}', NULL, 4, 758, 533),
(759, 'conversation', '/ˌkɒnvərˈseɪʃən/', 'noun', '{"zh-TW":["對話；交談"],"en":["a talk between two or more people"]}', NULL, 'have a conversation / casual conversation', '[{"en":"We had a long conversation.","zh-TW":"我們進行了一場長談。"},{"en":"I overheard their conversation.","zh-TW":"我無意間聽到了他們的對話。"}]', '{"verb":"converse","adjective":"conversational"}', NULL, 4, 759, NULL),
(760, 'convert', '/kənˈvɜːrt/', 'verb', '{"zh-TW":["轉換；改變"],"en":["to change from one form or use to another"]}', '{"prefix":{"text":"con-","meaning":"completely (完全)"},"root":{"text":"vert","meaning":"turn (轉)"},"logic":"完全轉變，即「轉換」。"}', 'convert currency/data/file', '[{"en":"The warehouse was converted into office space.","zh-TW":"倉庫被改建為辦公空間。"},{"en":"Please convert the amounts to US dollars.","zh-TW":"請將金額轉換為美元。"}]', '{"noun":"conversion"}', NULL, 3, 760, 734),
(761, 'convey', '/kənˈveɪ/', 'verb', '{"zh-TW":["傳達；運送"],"en":["to communicate a message or idea","to transport something"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"vey","meaning":"way/carry (路/攜帶)"},"logic":"一起帶走傳送，即「傳達」。"}', 'convey a message/meaning/impression', '[{"en":"The email failed to convey the urgency of the situation.","zh-TW":"電子郵件未能傳達情況的緊迫性。"},{"en":"Charts can convey complex data effectively.","zh-TW":"圖表可以有效傳達複雜數據。"}]', NULL, NULL, 2, 761, NULL),
(762, 'conveyance', '/kənˈveɪəns/', 'noun', '{"zh-TW":["不動產轉讓；運送"],"en":["the legal process of transferring ownership of property"]}', NULL, 'property conveyance / deed of conveyance', '[{"en":"All documents for the conveyance must be signed by both parties.","zh-TW":"不動產轉讓的所有文件必須由雙方簽署。"},{"en":"Conveyance fees are included in the total cost of purchasing property.","zh-TW":"不動產轉讓費包含在購房總費用中。"}]', '{"verb":"convey","noun":"conveyancer"}', NULL, 4, 762, 766),
(763, 'conviction', '/kənˈvɪkʃən/', 'noun', '{"zh-TW":["定罪；信念"],"en":["being found guilty of a crime"]}', NULL, 'criminal conviction / strong conviction', '[{"en":"He has no prior convictions.","zh-TW":"他沒有前科。"},{"en":"She spoke with strong conviction.","zh-TW":"她說話帶著堅定的信念。"}]', '{"verb":"convict"}', NULL, 4, 763, NULL),
(764, 'convince', '/kənˈvɪns/', 'verb', '{"zh-TW":["說服；使確信","說服"],"en":["to cause someone to believe something firmly","to make someone believe something"]}', '{"prefix":{"text":"con-","meaning":"completely (完全)"},"root":{"text":"vince","meaning":"conquer (征服)"},"logic":"完全征服某人的想法，即「說服」。"}', 'convince sb to do / convince sb that; convince someone to / hard to convince', '[{"en":"She convinced the board to approve the budget increase.","zh-TW":"她說服董事會批准增加預算。"},{"en":"The data convinced us that the strategy was working.","zh-TW":"數據使我們確信策略正在奏效。"},{"en":"She convinced me to try it.","zh-TW":"她說服我去嘗試。"},{"en":"I''m not convinced that''s the best option.","zh-TW":"我不確信那是最好的選擇。"}]', '{"adjective":"convincing"}', NULL, 3, 764, NULL),
(765, 'COO', '/ˌsiː oʊ ˈoʊ/', 'noun', '{"zh-TW":["營運長；首席營運官"],"en":["chief operating officer; the executive managing daily operations"]}', NULL, 'COO responsibilities / appoint a COO', '[{"en":"The COO is responsible for supply chain and production operations.","zh-TW":"營運長負責供應鏈和生產運營。"},{"en":"She was promoted to COO after successfully launching three products.","zh-TW":"她在成功推出三款產品後晉升為營運長。"}]', '{"full form":"chief operating officer"}', NULL, 1, 765, NULL),
(766, 'cook', '/kʊk/', 'verb', '{"zh-TW":["烹飪；廚師","烹飪；做飯"],"en":["to prepare food by heating","a person who cooks"]}', NULL, 'cook a meal / head cook; cook dinner / cook up', '[{"en":"She cooks dinner every evening.","zh-TW":"她每天晚上煮晚餐。"},{"en":"The restaurant hired a new head cook.","zh-TW":"餐廳聘請了一位新主廚。"},{"en":"Who''s cooking dinner tonight?","zh-TW":"今晚誰做飯？"},{"en":"She cooks really well.","zh-TW":"她做飯很好吃。"}]', '{"verb":"cook","noun":"cook","noun2":"cooking","noun3":"cooker"}', NULL, 1, 766, NULL),
(767, 'cookie', '/ˈkʊki/', 'noun', '{"zh-TW":["餅乾"],"en":["a small flat sweet cake"]}', NULL, 'chocolate chip cookie / cookie jar', '[{"en":"Would you like a cookie?","zh-TW":"你想要一塊餅乾嗎？"},{"en":"She baked cookies for the party.","zh-TW":"她為派對烤了餅乾。"}]', NULL, NULL, 2, 767, NULL),
(768, 'cool', '/kuːl/', 'adjective', '{"zh-TW":["涼爽的；冷靜的","涼的；酷的"],"en":["slightly cold","calm and relaxed","slightly cold; fashionable"]}', NULL, 'keep cool / cool down; cool down / keep cool', '[{"en":"Keep cool under pressure.","zh-TW":"在壓力下保持冷靜。"},{"en":"The weather is getting cooler.","zh-TW":"天氣變得越來越涼爽。"},{"en":"The weather is getting cool.","zh-TW":"天氣漸漸涼了。"},{"en":"That''s a really cool jacket.","zh-TW":"那件夾克真酷。"}]', '{"adjective":"cool","verb":"cool","noun":"coolness","adverb":"coolly"}', NULL, 1, 768, NULL),
(769, 'cooperate', '/kəʊˈɒpəreɪt/', 'verb', '{"zh-TW":["合作；配合","合作"],"en":["to work together toward a common goal"]}', '{"prefix":{"text":"co-","meaning":"together (一起)"},"root":{"text":"oper","meaning":"work (工作)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"一起工作，即「合作」。"}', 'cooperate with / cooperate closely; cooperate with / cooperate fully', '[{"en":"Both departments must cooperate to meet the deadline.","zh-TW":"兩個部門必須合作以趕上截止日期。"},{"en":"The company cooperated fully with the investigation.","zh-TW":"公司全力配合調查。"},{"en":"The two companies agreed to cooperate on the project.","zh-TW":"兩家公司同意在該專案上合作。"},{"en":"Please cooperate with the investigation.","zh-TW":"請配合調查。"}]', '{"noun":"cooperation","adjective":"cooperative"}', NULL, 3, 769, NULL),
(770, 'cooperation', 'koʊˌɒpəˈreɪʃən', 'noun', '{"zh-TW":["合作；協作","配合"],"en":["working together toward a goal","joint effort"]}', NULL, 'international cooperation/close cooperation', '[{"en":"Thank you for your cooperation.","zh-TW":"感謝您的合作。"}]', '{"verb":"cooperate","adjective":"cooperative","adverb":"cooperatively"}', NULL, 4, 770, 311),
(771, 'cooperative', '/koʊˈɒpərətɪv/', 'noun', '{"zh-TW":["合作社；合作企業"],"en":["a business owned and operated collectively by its members for shared benefit"]}', NULL, 'form a cooperative / cooperative member', '[{"en":"The farmers formed a cooperative to negotiate better prices for their produce.","zh-TW":"農民組成了一個合作社，以為其農產品談判更好的價格。"},{"en":"A consumer cooperative passes savings directly to its members.","zh-TW":"消費者合作社將節省直接轉給其成員。"}]', '{"adjective":"cooperative"}', NULL, 4, 771, NULL),
(772, 'coordinate', '/kəʊˈɔːrdɪneɪt/', 'verb', '{"zh-TW":["協調；統籌"],"en":["to organize different elements to work together effectively"]}', '{"prefix":{"text":"co-","meaning":"together (一起)"},"root":{"text":"ordin","meaning":"order (秩序)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使一起有秩序，即「協調」。"}', 'coordinate efforts/activities/schedules', '[{"en":"She coordinates all logistics for international shipments.","zh-TW":"她協調所有國際出貨的物流。"},{"en":"We need to coordinate our efforts across departments.","zh-TW":"我們需要跨部門協調努力。"}]', '{"noun":"coordination","noun2":"coordinator"}', NULL, 4, 772, 93),
(773, 'coordination', 'koʊˌɔːrdɪˈneɪʃən', 'noun', '{"zh-TW":["協調；配合","統籌"],"en":["the organization of people or tasks","working together smoothly"]}', NULL, 'project coordination/team coordination', '[{"en":"Good coordination is essential.","zh-TW":"良好的協調至關重要。"}]', '{"verb":"coordinate","adjective":"coordinated","adverb":"coordinately"}', NULL, 4, 773, 534),
(774, 'coordinator', '/koʊˈɔːrdɪneɪtər/', 'noun', '{"zh-TW":["協調員；統籌人員"],"en":["a person who organizes and manages activities within a team"]}', NULL, 'project coordinator / event coordinator / HR coordinator', '[{"en":"The project coordinator tracked deliverables and managed stakeholder communications.","zh-TW":"項目協調員追蹤可交付成果並管理利益相關者溝通。"},{"en":"She started as an HR coordinator before becoming a manager.","zh-TW":"她在成為經理前從人力資源協調員做起。"}]', '{"plural":"coordinators","verb":"coordinate"}', NULL, 4, 774, NULL),
(775, 'cope', '/koʊp/', 'verb', '{"zh-TW":["應付；處理"],"en":["to deal with something effectively"]}', '{"root":{"text":"cope","meaning":"strike/deal with (對付)"},"logic":"源自古法語 couper（打擊），引申為應對。"}', 'cope with / unable to cope', '[{"en":"She learned to cope with stress through meditation.","zh-TW":"她學會透過冥想來應對壓力。"},{"en":"He couldn''t cope with the workload.","zh-TW":"他無法應付工作量。"}]', '{"noun":"coping"}', NULL, 1, 775, NULL),
(776, 'copy', '/ˈkɒpi/', 'noun', '{"zh-TW":["副本；複製"],"en":["a thing made to be the same as another"]}', NULL, 'make a copy / carbon copy', '[{"en":"Can you make a copy of this?","zh-TW":"你能複印一份嗎？"},{"en":"Keep a copy for your records.","zh-TW":"保留一份副本作為記錄。"}]', '{"verb":"copy"}', NULL, 1, 776, 312),
(777, 'copyright', '/ˈkɒpiraɪt/', 'noun', '{"zh-TW":["著作權；版權"],"en":["the legal right to control creative work"]}', NULL, 'copyright law / copyright infringement', '[{"en":"The book is protected by copyright.","zh-TW":"這本書受著作權保護。"},{"en":"Copyright infringement is illegal.","zh-TW":"侵犯版權是違法的。"}]', NULL, NULL, 3, 777, NULL),
(778, 'copywriting', '/ˈkɒpiˌraɪtɪŋ/', 'noun', '{"zh-TW":["文案寫作"],"en":["the activity of writing promotional text for advertising"]}', NULL, 'persuasive copywriting / website copywriting / email copywriting', '[{"en":"Effective copywriting highlights the benefits rather than features.","zh-TW":"有效的文案寫作強調利益而非功能特點。"},{"en":"She specialized in SEO copywriting for e-commerce websites.","zh-TW":"她專精於電子商務網站的SEO文案寫作。"}]', '{"verb":"copywrite","noun":"copywriter"}', NULL, 4, 778, NULL),
(779, 'corkage', '/ˈkɔːrkɪdʒ/', 'noun', '{"zh-TW":["開瓶費"],"en":["a charge made for bringing your own bottle of wine to a restaurant"]}', NULL, 'corkage fee / corkage policy', '[{"en":"The restaurant charges a ten-dollar corkage fee per bottle.","zh-TW":"餐廳每瓶收取十元的開瓶費。"},{"en":"Ask about the corkage fee before bringing your own wine.","zh-TW":"自帶葡萄酒前請詢問開瓶費。"}]', NULL, NULL, 3, 779, NULL),
(780, 'corner', '/ˈkɔːrnər/', 'noun', '{"zh-TW":["角落；轉角","角落；拐角"],"en":["a point where two lines or surfaces meet","a place near where two roads meet","the point where two lines or walls meet"]}', NULL, 'around the corner / cut corners', '[{"en":"The coffee shop is around the corner.","zh-TW":"咖啡店就在轉角。"},{"en":"We cannot cut corners on safety.","zh-TW":"我們不能在安全方面偷工減料。"},{"en":"There''s a shop on the corner.","zh-TW":"拐角處有一家商店。"},{"en":"Success is just around the corner.","zh-TW":"成功就在眼前。"}]', '{"noun":"corner","verb":"corner"}', NULL, 2, 780, NULL),
(781, 'corporate', '/ˈkɔːrpərət/', 'adjective', '{"zh-TW":["企業的；公司的","公司的；企業的"],"en":["relating to a large company or group"]}', '{"root":{"text":"corpor","meaning":"body (身體)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"具有團體身體（法人）的，即「企業的」。"}', 'corporate culture / corporate governance / corporate strategy; corporate culture / corporate responsibility', '[{"en":"The corporate headquarters is located in New York.","zh-TW":"公司總部位於紐約。"},{"en":"Strong corporate governance builds investor trust.","zh-TW":"良好的公司治理建立投資者信任。"},{"en":"The corporate headquarters is in New York.","zh-TW":"公司總部在紐約。"},{"en":"Corporate responsibility is increasingly important.","zh-TW":"企業責任越來越重要。"}]', '{"noun":"corporation"}', NULL, 3, 781, NULL),
(782, 'corporation', 'ˌkɔːrpəˈreɪʃən', 'noun', '{"zh-TW":["公司；企業","法人"],"en":["a large company","a legal entity"]}', NULL, 'large corporation/multinational corporation', '[{"en":"The corporation has offices in 20 countries.","zh-TW":"該企業在20個國家有辦事處。"}]', '{"adjective":"corporate","adverb":"corporately"}', NULL, 4, 782, 94),
(783, 'correct', '/kəˈrɛkt/', 'adjective', '{"zh-TW":["正確的；糾正","正確的"],"en":["right; without errors","to make right","right; without mistakes"]}', NULL, 'correct answer / correct a mistake; correct answer / politically correct', '[{"en":"Is this information correct?","zh-TW":"這個資訊正確嗎？"},{"en":"Please correct any errors in the report.","zh-TW":"請更正報告中的錯誤。"},{"en":"Your answer is correct.","zh-TW":"你的答案是正確的。"},{"en":"Please correct any errors.","zh-TW":"請改正任何錯誤。"}]', '{"adjective":"correct","verb":"correct","noun":"correction","adverb":"correctly"}', NULL, 3, 783, 313),
(784, 'correction', 'kəˈrɛkʃən', 'noun', '{"zh-TW":["更正；修正","訂正"],"en":["a change to fix an error","something that makes something right"]}', NULL, 'make a correction/correction notice', '[{"en":"Please note the correction in paragraph 3.","zh-TW":"請注意第3段的更正。"}]', '{"verb":"correct","adjective":"correct","adverb":"correctly"}', NULL, 4, 784, NULL),
(785, 'correspond', '/ˌkɒrɪˈspɒnd/', 'verb', '{"zh-TW":["對應；通信"],"en":["to be similar or equivalent to","to communicate by letter or email"]}', '{"prefix":{"text":"cor-","meaning":"together (一起)"},"root":{"text":"respond","meaning":"answer (回應)"},"logic":"一起回應，即「對應、通信」。"}', 'correspond to/with / correspond by email', '[{"en":"The results correspond to our initial predictions.","zh-TW":"結果與我們最初的預測相符。"},{"en":"We have been corresponding by email for months.","zh-TW":"我們已通過電子郵件通信數月。"}]', '{"noun":"correspondence"}', NULL, 4, 785, 95),
(786, 'correspondence', '/ˌkɒrɪˈspɒndəns/', 'noun', '{"zh-TW":["通訊；信件往來"],"en":["written communication, especially letters and emails in a business context"]}', NULL, 'business correspondence / official correspondence / maintain correspondence', '[{"en":"All correspondence with clients must be professional and timely.","zh-TW":"與客戶的所有通訊必須專業且及時。"},{"en":"She reviewed the correspondence before the meeting.","zh-TW":"她在會議前審閱了通訊記錄。"}]', '{"verb":"correspond","noun":"correspondent","adjective":"corresponding"}', NULL, 5, 786, 535),
(787, 'cost', '/kɒst/', 'noun', '{"zh-TW":["成本；費用"],"en":["the amount of money needed to buy or do something"]}', '{"root":{"text":"cost","meaning":"stand at a price (定價)"},"logic":"定價，即「成本」。"}', 'cost-effective / at all costs / reduce costs', '[{"en":"We need to reduce operating costs by 15%.","zh-TW":"我們需要將營運成本降低15%。"},{"en":"The total cost exceeded the original estimate.","zh-TW":"總成本超過了原始估算。"}]', '{"adjective":"costly"}', NULL, 1, 787, NULL),
(788, 'cost-effective', 'kɒst ɪˈfɛktɪv', 'adjective', '{"zh-TW":["具有成本效益的；划算的","經濟實惠的"],"en":["giving good value for money","efficient use of resources"]}', NULL, 'cost-effective solution/cost-effective approach', '[{"en":"This is the most cost-effective option.","zh-TW":"這是最具成本效益的選項。"}]', '{"noun":"cost-effectiveness","adverb":"cost-effectively"}', NULL, 5, 788, NULL),
(789, 'costs', 'kɒsts', 'noun', '{"zh-TW":["費用；成本","代價"],"en":["amounts paid for goods","expenses"]}', NULL, 'operating costs/reduce costs', '[{"en":"We must control operating costs.","zh-TW":"我們必須控制運營成本。"}]', '{"verb":"cost","adjective":"costly","adverb":"costlily"}', NULL, 2, 789, NULL),
(790, 'cotton', '/ˈkɒtən/', 'noun', '{"zh-TW":["棉花；棉布"],"en":["a soft white material used for making cloth"]}', NULL, 'cotton shirt / cotton candy', '[{"en":"This shirt is made of cotton.","zh-TW":"這件襯衫是棉做的。"},{"en":"Cotton is grown in warm climates.","zh-TW":"棉花生長在溫暖的氣候中。"}]', NULL, NULL, 2, 790, NULL),
(791, 'council', '/ˈkaʊnsl/', 'noun', '{"zh-TW":["委員會；議會"],"en":["an advisory or legislative body of people"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"cil","meaning":"call (召集)"},"logic":"一起被召集的人，即「委員會」。"}', 'city council / council meeting / council member', '[{"en":"The city council approved the new development plan.","zh-TW":"市議會批准了新的開發計畫。"},{"en":"A council meeting is scheduled for next Tuesday.","zh-TW":"委員會會議安排在下週二。"}]', NULL, NULL, 3, 791, NULL),
(792, 'counsel', '/ˈkaʊnsl/', 'noun', '{"zh-TW":["勸告；律師","建議"],"en":["advice given formally","a lawyer representing someone"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sel","meaning":"take/consult (取/諮詢)"},"logic":"一起諮詢，即「勸告」。"}', 'legal counsel / seek counsel / general counsel', '[{"en":"The firm hired outside legal counsel for the case.","zh-TW":"公司為此案聘請了外部法律顧問。"},{"en":"I would counsel patience in this situation.","zh-TW":"我建議在這種情況下保持耐心。"}]', '{"noun":"counselor"}', NULL, 3, 792, NULL),
(793, 'count', '/kaʊnt/', 'verb', '{"zh-TW":["【主要意義-動詞/名詞】計算；數數","【次要意義-動詞】重要；有意義；被計入","【次要意義-名詞】（法律）罪名；指控"],"en":["[primary] to calculate the number of something","[secondary - verb] to be significant or valid; to be included","[secondary - noun] a specific charge in a legal case"]}', NULL, 'count on / count toward / every vote counts / count against / on all counts', '[{"en":"Every customer complaint counts toward the quarterly performance review.","zh-TW":"每一個客戶投訴都計入季度績效評估。"},{"en":"Experience in project management will count in your favor.","zh-TW":"專案管理經驗將對你有利。"},{"en":"The defendant was found guilty on all three counts.","zh-TW":"被告在三項罪名上均被裁定有罪。"}]', '{"noun":"recount","adjective":"countless"}', '動詞 count = 「重要/被計入」，count on（依靠），count toward（計入），count against（不利於），這些片語在 TOEIC 商業或法律語境中頻繁出現。', 2, 793, NULL),
(794, 'counter', '/ˈkaʊntər/', 'noun', '{"zh-TW":["櫃台；計數器"],"en":["a flat surface in a kitchen or shop"]}', NULL, 'over the counter / counter offer', '[{"en":"Leave the keys on the counter.","zh-TW":"把鑰匙放在櫃台上。"},{"en":"The medicine is available over the counter.","zh-TW":"這個藥不需要處方就能買到。"}]', NULL, NULL, 3, 794, NULL),
(795, 'counteroffer', '/ˈkaʊntərˌɒfər/', 'noun', '{"zh-TW":["反要約；還價"],"en":["an offer made in response to a previous offer, typically with different terms"]}', NULL, 'make a counteroffer / accept a counteroffer', '[{"en":"The supplier made a counteroffer with a 5% lower price than originally proposed.","zh-TW":"供應商提出了比最初提議低5%的反要約。"},{"en":"The buyer rejected the counteroffer and walked away from the deal.","zh-TW":"買方拒絕了反要約並放棄了交易。"}]', '{"verb":"counteroffer"}', NULL, 4, 795, NULL),
(796, 'counterpart', '/ˈkaʊntərpɑːrt/', 'noun', '{"zh-TW":["對應的人或物"],"en":["a person or thing with the same function in a different situation"]}', NULL, 'overseas counterpart / business counterpart', '[{"en":"I met with my Japanese counterpart.","zh-TW":"我與我的日本對口人員會面。"},{"en":"Their product is superior to its counterparts.","zh-TW":"他們的產品優於同類產品。"}]', '{"noun":"counterpart"}', NULL, 4, 796, 663),
(797, 'counterparty', '/ˈkaʊntərˌpɑːrti/', 'noun', '{"zh-TW":["對手方；交易對手"],"en":["the other party in a financial transaction or contract"]}', NULL, 'assess counterparty risk / identify the counterparty', '[{"en":"The bank assessed the counterparty''s credit rating before signing.","zh-TW":"銀行在簽署前評估了對手方的信用評級。"},{"en":"Counterparty risk is a major concern in derivatives markets.","zh-TW":"在衍生品市場中，對手方風險是一個主要問題。"}]', NULL, NULL, 4, 797, NULL),
(798, 'country', '/ˈkʌntri/', 'noun', '{"zh-TW":["國家；鄉村"],"en":["a nation","rural areas outside cities","a nation with its own government"]}', NULL, 'home country / country of origin; home country / country side', '[{"en":"Which country are you from?","zh-TW":"你來自哪個國家？"},{"en":"The product''s country of origin is Japan.","zh-TW":"產品的原產國是日本。"},{"en":"They live in the countryside.","zh-TW":"他們住在鄉下。"}]', '{"noun":"country","noun2":"countryside"}', NULL, 3, 798, NULL),
(799, 'county', '/ˈkaʊnti/', 'noun', '{"zh-TW":["郡；縣"],"en":["a region of a country"]}', NULL, 'county court / county fair', '[{"en":"She lives in Orange County.","zh-TW":"她住在橘郡。"},{"en":"The county fair is in August.","zh-TW":"縣集市在八月舉行。"}]', NULL, NULL, 2, 799, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(800, 'couple', '/ˈkʌpəl/', 'noun', '{"zh-TW":["一對；幾個","一對；一些"],"en":["two people together","a small number","two people together; a few"]}', NULL, 'a couple of / married couple', '[{"en":"I need a couple of days to finish.","zh-TW":"我需要幾天來完成。"},{"en":"The couple next door just moved in.","zh-TW":"隔壁那對夫妻剛搬進來。"},{"en":"A couple of days ago, I saw him.","zh-TW":"幾天前我看到他了。"},{"en":"They make a lovely couple.","zh-TW":"他們是很可愛的一對。"}]', '{"noun":"couple","verb":"couple"}', NULL, 2, 800, NULL),
(801, 'coupon', '/ˈkuːpɒn/', 'noun', '{"zh-TW":["優惠券；折價券"],"en":["a voucher giving a discount on a product"]}', '{"root":{"text":"coupon","meaning":"cut piece (切下的紙片)"},"logic":"源自法語 couper（剪），指剪下的折價券。"}', 'discount coupon / redeem a coupon', '[{"en":"I have a coupon for 20% off.","zh-TW":"我有一張八折優惠券。"},{"en":"Customers can redeem coupons at checkout.","zh-TW":"顧客可以在結帳時兌換優惠券。"}]', NULL, NULL, 2, 801, NULL),
(802, 'courage', '/ˈkɜːrɪdʒ/', 'noun', '{"zh-TW":["勇氣"],"en":["the ability to face danger without fear"]}', NULL, 'have the courage / take courage', '[{"en":"It takes courage to speak up.","zh-TW":"站出來發言需要勇氣。"},{"en":"She showed great courage.","zh-TW":"她展現了極大的勇氣。"}]', '{"adjective":"courageous"}', NULL, 3, 802, NULL),
(803, 'courageous', '/kəˈreɪdʒəs/', 'adjective', '{"zh-TW":["勇敢的"],"en":["not afraid of danger or difficulties"]}', '{"root":{"text":"courage","meaning":"heart (心)"},"suffix":{"text":"-ous","meaning":"full of (充滿)"},"logic":"充滿勇氣的，即「勇敢的」。"}', 'courageous act / courageous decision', '[{"en":"It was a courageous decision to speak up.","zh-TW":"站出來發聲是勇敢的決定。"},{"en":"The firefighters were incredibly courageous.","zh-TW":"消防隊員們非常英勇。"}]', '{"noun":"courage","adverb":"courageously"}', NULL, 4, 803, NULL),
(804, 'courier', '/ˈkʊriər/', 'noun', '{"zh-TW":["快遞員；信差"],"en":["a person or company that transports documents or packages quickly"]}', NULL, 'send by courier / courier service / international courier', '[{"en":"The documents were sent by courier to arrive the next morning.","zh-TW":"文件通過快遞發送，次日早上到達。"},{"en":"An international courier service was used to ship the samples.","zh-TW":"使用了國際快遞服務運送樣品。"}]', '{"verb":"courier"}', NULL, 3, 804, NULL),
(805, 'course', '/kɔːrs/', 'noun', '{"zh-TW":["課程；過程"],"en":["a series of lessons","a direction or path"]}', NULL, 'of course / training course', '[{"en":"I enrolled in a training course.","zh-TW":"我報名了一個培訓課程。"},{"en":"Of course, I will help you.","zh-TW":"當然，我會幫你。"}]', '{"noun":"course"}', NULL, 2, 805, NULL),
(806, 'coursework', '/ˈkɔːrswɜːrk/', 'noun', '{"zh-TW":["課程作業；學術作業"],"en":["written or practical work contributing to a final grade"]}', NULL, 'submit coursework / complete coursework', '[{"en":"Her coursework accounts for 40% of the final grade.","zh-TW":"她的課程作業佔最終成績的40%。"},{"en":"Completing coursework on time demonstrates responsibility.","zh-TW":"按時完成課程作業展示了責任感。"}]', NULL, NULL, 4, 806, NULL),
(807, 'court', '/kɔːrt/', 'noun', '{"zh-TW":["法庭；球場"],"en":["a place where legal cases are heard"]}', NULL, 'go to court / tennis court', '[{"en":"The case went to court.","zh-TW":"案件上了法庭。"},{"en":"We booked a tennis court.","zh-TW":"我們預訂了一個網球場。"}]', NULL, NULL, 2, 807, NULL),
(808, 'courtesy', '/ˈkɜːrtɪsi/', 'noun', '{"zh-TW":["禮貌；禮節"],"en":["polite behavior; or something provided free of charge as a favor"]}', NULL, 'courtesy call / courtesy van', '[{"en":"The hotel provides a courtesy van to the airport.","zh-TW":"飯店提供接送機場的禮賓車。"},{"en":"She received a courtesy call confirming her reservation.","zh-TW":"她收到了確認預訂的禮貌電話。"}]', '{"adjective":"courteous","adverb":"courteously"}', NULL, 3, 808, NULL),
(809, 'cousin', '/ˈkʌzən/', 'noun', '{"zh-TW":["表兄弟姊妹"],"en":["the child of your aunt or uncle"]}', NULL, 'first cousin / distant cousin', '[{"en":"My cousin lives in Canada.","zh-TW":"我表哥住在加拿大。"},{"en":"We''re first cousins.","zh-TW":"我們是表兄弟。"}]', NULL, NULL, 2, 809, NULL),
(810, 'covenant', '/ˈkʌvənənt/', 'noun', '{"zh-TW":["契約；約定條款"],"en":["a formal agreement or a restriction imposed in a financial contract"]}', NULL, 'financial covenant / loan covenant / breach a covenant', '[{"en":"The loan agreement includes a covenant limiting additional borrowing.","zh-TW":"貸款協議包含限制額外借款的約定條款。"},{"en":"Breaching the financial covenant triggered a review by the lenders.","zh-TW":"違反財務約定條款觸發了貸款方的審查。"}]', '{"verb":"covenant"}', NULL, 3, 810, NULL),
(811, 'cover', '/ˈkʌvər/', 'verb', '{"zh-TW":["【主要意義-動詞/名詞】覆蓋；封面","【次要意義-動詞】代替（同事）；代班","【次要意義-動詞】涵蓋範圍；包含","【次要意義-名詞】保險保障；掩護"],"en":["[primary] to place something over something else; an outer layer","[secondary - verb] to do someone else job while they are away","[secondary - verb] to include or deal with in scope","[secondary - noun] insurance protection; a pretense for hiding something"]}', NULL, 'cover for someone / cover a story / insurance cover / cover letter / under cover', '[{"en":"Can you cover for me while I attend the training session?","zh-TW":"我參加培訓課程時你能替我代班嗎？"},{"en":"The insurance policy covers all medical expenses incurred abroad.","zh-TW":"保險單涵蓋了在國外產生的所有醫療費用。"},{"en":"The seminar will cover topics ranging from marketing to finance.","zh-TW":"研討會將涵蓋從市場營銷到財務的各種主題。"}]', '{"noun":"coverage","adjective":"undercover"}', 'cover 的次要意義：cover for（代班）、insurance cover（保險保障）、cover letter（求職信）均為 TOEIC 職場文章必考詞彙，考生容易只記住「覆蓋」的意思。', 2, 811, NULL),
(812, 'coverage', '/ˈkʌvərɪdʒ/', 'noun', '{"zh-TW":["保險承保範圍"],"en":["the extent of protection provided by insurance"]}', NULL, 'insurance coverage / comprehensive coverage', '[{"en":"Check whether dental care is included in your coverage.","zh-TW":"確認您的保險承保範圍是否包含牙科護理。"},{"en":"Her policy provides coverage for hospitalization.","zh-TW":"她的保單提供住院承保。"}]', '{"verb":"cover","adjective":"covered"}', NULL, 3, 812, 96),
(813, 'cow', '/kaʊ/', 'noun', '{"zh-TW":["牛；母牛"],"en":["a large female farm animal that produces milk"]}', NULL, 'dairy cow / cow milk', '[{"en":"The farmer milks the cows every morning.","zh-TW":"農夫每天早上擠牛奶。"},{"en":"Cows eat grass in the field.","zh-TW":"牛在田裡吃草。"}]', NULL, NULL, 1, 813, NULL),
(814, 'crack', '/kræk/', 'noun', '{"zh-TW":["【主要意義-動詞/名詞】破裂；裂縫","【次要意義-形容詞】優秀的；一流的；精銳的","【次要意義-動詞】解決（問題）；破解（密碼）","【次要意義-名詞】嘗試；機會（have a crack at）"],"en":["[primary] to break partially; a narrow opening or line of damage","[secondary - adjective] highly skilled or expert","[secondary - verb] to find the solution to something difficult","[secondary - noun] an attempt at something"]}', NULL, 'a crack team / crack the code / crack down on / have a crack at / crack of dawn', '[{"en":"She joined the crack negotiating team sent to close the deal.","zh-TW":"她加入了派去完成交易的精銳談判團隊。"},{"en":"The new software engineers managed to crack the encryption problem.","zh-TW":"新的軟體工程師成功破解了加密問題。"},{"en":"Regulators are cracking down on companies that violate data privacy laws.","zh-TW":"監管機構正在加強打擊違反數據隱私法的公司。"}]', '{"noun":"crackdown","adjective":"cracked"}', '形容詞 crack = 「一流的/精銳的」（a crack team），crack down on（嚴厲打擊），have a crack at（嘗試），均是 TOEIC 商業和法規文章的高頻表達，考生容易只認識名詞「裂縫」。', 2, 814, NULL),
(815, 'craft', '/kræft/', 'noun', '{"zh-TW":["工藝；手藝"],"en":["an activity involving skilled making of things by hand","an activity involving skill in making things by hand"]}', '{"root":{"text":"craft","meaning":"strength/skill (力量/技藝)"},"logic":"源自古英語 cræft（力量、技能）。"}', 'arts and crafts / craft beer; arts and crafts / craft beer / master one''s craft', '[{"en":"She''s skilled in traditional crafts.","zh-TW":"她擅長傳統工藝。"},{"en":"Craft beer has become very popular.","zh-TW":"精釀啤酒變得非常受歡迎。"},{"en":"She learned the craft of pottery making.","zh-TW":"她學會了陶藝的手藝。"},{"en":"Local crafts are sold at the market.","zh-TW":"當地手工藝品在市場販售。"}]', '{"noun2":"craftsman","adjective":"crafty","noun":"craftsman","verb":"craft"}', NULL, 2, 815, NULL),
(816, 'crash', '/kræʃ/', 'noun', '{"zh-TW":["碰撞；崩潰"],"en":["a violent collision; a sudden failure"]}', NULL, 'car crash / system crash', '[{"en":"There was a car crash on the highway.","zh-TW":"高速公路上發生了車禍。"},{"en":"The computer crashed again.","zh-TW":"電腦又當機了。"}]', '{"verb":"crash"}', NULL, 2, 816, NULL),
(817, 'crazy', '/ˈkreɪzi/', 'adjective', '{"zh-TW":["瘋狂的"],"en":["very foolish; mentally ill"]}', NULL, 'go crazy / crazy about', '[{"en":"That''s a crazy idea!","zh-TW":"那是個瘋狂的想法！"},{"en":"She''s crazy about music.","zh-TW":"她對音樂非常著迷。"}]', NULL, NULL, 2, 817, NULL),
(818, 'cream', '/kriːm/', 'noun', '{"zh-TW":["奶油；乳霜"],"en":["the thick white liquid from milk"]}', NULL, 'ice cream / cream cheese', '[{"en":"I''d like cream in my coffee.","zh-TW":"我的咖啡要加奶油。"},{"en":"Apply this cream twice daily.","zh-TW":"每天塗兩次這個乳霜。"}]', '{"adjective":"creamy"}', NULL, 2, 818, NULL),
(819, 'create', '/kriˈeɪt/', 'verb', '{"zh-TW":["創造；建立"],"en":["to bring something into existence"]}', '{"root":{"text":"cre","meaning":"grow/make (成長/製造)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"使成長出來，即「創造」。"}', 'create value/opportunities/jobs', '[{"en":"The merger will create the largest company in the sector.","zh-TW":"合併將創建該行業最大的公司。"},{"en":"Innovation creates new business opportunities.","zh-TW":"創新創造了新的商業機會。"}]', '{"noun":"creation","adjective":"creative","noun2":"creativity"}', NULL, 2, 819, 314),
(820, 'creative', '/kriˈeɪtɪv/', 'adjective', '{"zh-TW":["有創意的"],"en":["involving the use of imagination to produce new ideas"]}', '{"root":{"text":"creat","meaning":"make (創造)"},"suffix":{"text":"-ive","meaning":"having quality of (具有…特質)"},"logic":"具有創造特質的。"}', 'creative thinking / creative director', '[{"en":"She found a creative solution to the problem.","zh-TW":"她找到了一個有創意的解決方案。"},{"en":"The job requires creative thinking.","zh-TW":"這份工作需要創意思考。"}]', '{"noun":"creativity","verb":"create","noun2":"creation"}', NULL, 3, 820, NULL),
(821, 'creature', '/ˈkriːtʃər/', 'noun', '{"zh-TW":["生物；動物"],"en":["any living thing that is not a plant"]}', NULL, 'living creature / sea creature', '[{"en":"Strange creatures live in the deep sea.","zh-TW":"奇怪的生物生活在深海中。"},{"en":"Every creature deserves respect.","zh-TW":"每一個生物都值得被尊重。"}]', NULL, NULL, 3, 821, NULL),
(822, 'credential', '/krɪˈdɛnʃəl/', 'noun', '{"zh-TW":["資格證明；證書"],"en":["qualifications or achievements that prove capability"]}', NULL, 'professional credentials / verify credentials', '[{"en":"Please verify the candidate''s credentials.","zh-TW":"請驗證候選人的資歷。"},{"en":"His credentials include an MBA and CPA.","zh-TW":"他的資歷包括MBA和CPA。"}]', '{"noun":"credential","adjective":"credentialed"}', NULL, 4, 822, NULL),
(823, 'credibility', '/ˌkredɪˈbɪlɪti/', 'noun', '{"zh-TW":["可信度；信譽"],"en":["the quality of being trusted and believed in"]}', NULL, 'build credibility / establish credibility / credibility with investors', '[{"en":"The auditor''s report added credibility to the financial statements.","zh-TW":"審計師的報告增加了財務報表的可信度。"},{"en":"A strong track record builds credibility with customers and partners.","zh-TW":"強勁的業績記錄建立了對客戶和合作夥伴的信譽。"}]', '{"adjective":"credible","adverb":"credibly"}', NULL, 4, 823, NULL),
(824, 'credit', '/ˈkredɪt/', 'noun', '{"zh-TW":["信用；學分","功勞","信用；學分；功勞"],"en":["the ability to borrow money","praise or acknowledgment","the ability to buy now and pay later"]}', '{"root":{"text":"cred","meaning":"believe (相信)"},"suffix":{"text":"-it","meaning":"thing (事物)"},"logic":"被相信（可還款）的，即「信用」。"}', 'credit card / credit rating / take credit for; credit card / take credit', '[{"en":"The company has a strong credit rating.","zh-TW":"公司擁有良好的信用評級。"},{"en":"Credit sales increased by 12% this quarter.","zh-TW":"本季度信用銷售增長了12%。"},{"en":"She paid by credit card.","zh-TW":"她用信用卡付款。"},{"en":"Give credit where it''s due.","zh-TW":"該給的功勞要給。"}]', '{"noun":"creditor","adjective":"credible","verb":"credit","noun2":"creditor"}', NULL, 2, 824, NULL),
(825, 'creditor', '/ˈkredɪtər/', 'noun', '{"zh-TW":["債權人；貸款方"],"en":["a person or company to whom money is owed"]}', NULL, 'secured creditor / unsecured creditor / creditor rights', '[{"en":"Creditors were notified of the company''s insolvency.","zh-TW":"債權人被告知公司的資不抵債情況。"},{"en":"The bank is a major creditor of the struggling retailer.","zh-TW":"銀行是這家陷入困境的零售商的主要債權人。"}]', '{"opposite":"debtor"}', NULL, 3, 825, NULL),
(826, 'creditworthy', '/ˈkredɪtˌwɜːrði/', 'adjective', '{"zh-TW":["信用良好的；值得信貸的"],"en":["considered likely to repay loans reliably"]}', NULL, 'creditworthy borrower / assess creditworthiness', '[{"en":"Only creditworthy applicants are approved for the credit facility.","zh-TW":"只有信用良好的申請者才能獲批信貸額度。"},{"en":"The company worked to become more creditworthy by reducing debt.","zh-TW":"公司通過減少債務來提高其信用水準。"}]', '{"noun":"creditworthiness"}', NULL, 4, 826, NULL),
