(831, 'criteria', '/kraɪˈtɪəriə/', 'noun', '{"zh-TW":["標準；準則（複數）","標準（複數）"],"en":["standards by which something is judged","principles used to judge or decide something"]}', '{"root":{"text":"crit","meaning":"judge (判斷)"},"suffix":{"text":"-eria","meaning":"plural (複數)"},"logic":"用來判斷的標準，即「準則」。"}', 'meet criteria / selection criteria / evaluation criteria; meet the criteria / selection criteria / strict criteria', '[{"en":"Applicants must meet all the selection criteria.","zh-TW":"申請者必須符合所有篩選標準。"},{"en":"What criteria did you use to evaluate the proposals?","zh-TW":"你用什麼標準來評估提案？"},{"en":"Applicants must meet all the criteria.","zh-TW":"申請者必須符合所有標準。"},{"en":"What criteria did you use to make the decision?","zh-TW":"你用什麼標準做出決定？"}]', '{"noun":"criterion","noun_singular":"criterion"}', NULL, 3, 831, 315),
(832, 'criterion', '/kraɪˈtɪəriən/', 'noun', '{"zh-TW":["標準；準則（單數）"],"en":["a principle or standard by which something is judged"]}', '{"root":{"text":"crit","meaning":"judge (判斷)"},"suffix":{"text":"-erion","meaning":"thing (事物)"},"logic":"用來判斷的事物，即「標準」。"}', 'main criterion / selection criterion / meet the criterion', '[{"en":"Price is not the only criterion for selection.","zh-TW":"價格不是選擇的唯一標準。"},{"en":"The main criterion is prior experience.","zh-TW":"主要標準是先前的經驗。"}]', '{"noun":"criteria"}', NULL, 3, 832, NULL),
(833, 'critic', '/ˈkrɪtɪk/', 'noun', '{"zh-TW":["評論家；批評者"],"en":["a person who judges the quality of art, music, or literature"]}', '{"root":{"text":"crit","meaning":"judge (判斷)"},"suffix":{"text":"-ic","meaning":"person (人)"},"logic":"做出判斷的人，即「評論家」。"}', 'film critic / art critic / harsh critic', '[{"en":"The critics praised the new film.","zh-TW":"影評人稱讚這部新電影。"},{"en":"He is a well-known food critic.","zh-TW":"他是知名的美食評論家。"}]', '{"noun":"criticism","adjective":"critical","verb":"criticize"}', NULL, 2, 833, NULL),
(834, 'critical', '/ˈkrɪtɪkəl/', 'adjective', '{"zh-TW":["批評的；關鍵的；危急的"],"en":["very important; expressing disapproval"]}', NULL, 'critical thinking / critical condition', '[{"en":"Critical thinking is an essential skill.","zh-TW":"批判性思維是必備技能。"},{"en":"The patient is in critical condition.","zh-TW":"病人情況危急。"}]', '{"noun":"criticism","verb":"criticize","noun2":"critic"}', NULL, 3, 834, 848),
(835, 'CRM', '/ˌsiː ɑːr ˈem/', 'noun', '{"zh-TW":["客戶關係管理"],"en":["customer relationship management; software or strategy for managing customer interactions"]}', NULL, 'CRM system / CRM software / implement CRM / update the CRM', '[{"en":"The CRM system tracks all customer communications in one place.","zh-TW":"CRM系統將所有客戶通信集中在一個地方追蹤。"},{"en":"Sales reps must log every call in the CRM.","zh-TW":"銷售代表必須在CRM中記錄每一次通話。"}]', '{"full form":"customer relationship management"}', NULL, 1, 835, NULL),
