(837, 'cross', '/krɒs/', 'verb', '{"zh-TW":["【主要意義-名詞/動詞】十字形；穿越","【次要意義-形容詞】生氣的；易怒的；惱火的"],"en":["[primary] a shape like + or x; to go across","[secondary - adjective] annoyed or angry"]}', NULL, 'cross with someone / at cross purposes', '[{"en":"The manager was cross with the team for missing the deadline.","zh-TW":"經理對團隊錯過截止日期感到惱火。"},{"en":"She seemed rather cross when her proposal was rejected.","zh-TW":"當她的提案被拒絕時，她顯得相當生氣。"},{"en":"They were talking at cross purposes during negotiation.","zh-TW":"他們在談判中各說各話，目的不同。"}]', '{"adverb":"crossly","noun":"crossness"}', 'cross 作形容詞意為「生氣的/惱火的」，是英式英語常見用法，TOEIC 閱讀中出現時容易被誤解為動詞「穿越」，at cross purposes（目的相左）是高階詞彙。', 2, 837, NULL),
(838, 'cross-border', '/ˈkrɒs ˌbɔːrdər/', 'adjective', '{"zh-TW":["跨境的；跨國的"],"en":["involving movement or activity across international borders"]}', NULL, 'cross-border transaction / cross-border merger / cross-border e-commerce', '[{"en":"Cross-border transactions require compliance with multiple regulatory regimes.","zh-TW":"跨境交易需要遵守多個監管制度。"},{"en":"Cross-border e-commerce is growing rapidly in emerging markets.","zh-TW":"跨境電子商務在新興市場快速增長。"}]', NULL, NULL, 4, 838, NULL),
(839, 'cross-functional', '/krɒs ˈfʌŋkʃənəl/', 'adjective', '{"zh-TW":["跨部門的；跨功能的"],"en":["involving people from different areas of an organization"]}', NULL, 'cross-functional team / cross-functional collaboration', '[{"en":"A cross-functional team was formed to solve the problem.","zh-TW":"成立了一個跨部門團隊來解決這個問題。"},{"en":"Cross-functional collaboration improves innovation and communication.","zh-TW":"跨部門合作促進了創新和溝通。"}]', NULL, NULL, 5, 839, NULL),
(840, 'cross-sell', '/krɒs sel/', 'verb', '{"zh-TW":["交叉銷售"],"en":["to persuade an existing customer to buy additional related products"]}', NULL, 'cross-sell products / cross-sell opportunity / cross-selling strategy', '[{"en":"Bank staff are trained to cross-sell insurance and investment products.","zh-TW":"銀行員工接受培訓，向客戶交叉銷售保險和投資產品。"},{"en":"Cross-selling increased average revenue per customer by 25%.","zh-TW":"交叉銷售使每位客戶的平均收入增加了25%。"}]', '{"noun":"cross-selling","adjective":"cross-sell"}', NULL, 4, 840, NULL),
(841, 'cross-selling', '/ˈkrɒsselɪŋ/', 'noun', '{"zh-TW":["交叉銷售"],"en":["encouraging customers to buy complementary products or services"]}', NULL, 'cross-selling opportunity / cross-selling strategy / effective cross-selling', '[{"en":"Cross-selling insurance products alongside mortgages boosts revenue.","zh-TW":"在抵押貸款旁邊交叉銷售保險產品可提升收入。"},{"en":"The CRM system helps identify cross-selling opportunities.","zh-TW":"CRM系統幫助識別交叉銷售機會。"}]', '{"verb":"cross-sell"}', NULL, 5, 841, NULL),
