(844, 'crucial', '/ˈkruːʃl/', 'adjective', '{"zh-TW":["關鍵的；至關重要的"],"en":["of great importance; critical","of great importance; decisive"]}', '{"root":{"text":"cruc","meaning":"cross (十字)"},"suffix":{"text":"-ial","meaning":"relating to (有關的)"},"logic":"在十字路口的（決定性的），即「關鍵的」。"}', 'crucial role/factor/decision; crucial role / crucial decision / crucial moment', '[{"en":"Timing is crucial for the success of this launch.","zh-TW":"時機對此次發布的成功至關重要。"},{"en":"Communication plays a crucial role in teamwork.","zh-TW":"溝通在團隊合作中扮演關鍵角色。"},{"en":"Teamwork is crucial to success.","zh-TW":"團隊合作對成功至關重要。"},{"en":"This is a crucial moment in the negotiations.","zh-TW":"這是談判中的關鍵時刻。"}]', '{"adverb":"crucially"}', NULL, 3, 844, NULL),
