(848, 'cry', '/kraɪ/', 'verb', '{"zh-TW":["哭；喊叫"],"en":["to produce tears","to shout","to produce tears from your eyes"]}', NULL, 'cry out / a far cry from; cry out / far cry', '[{"en":"This result is a far cry from what we expected.","zh-TW":"這個結果跟我們預期的相差甚遠。"},{"en":"She cried tears of joy.","zh-TW":"她喜極而泣。"},{"en":"The baby started to cry.","zh-TW":"寶寶開始哭了。"},{"en":"She cried out for help.","zh-TW":"她大聲呼救。"}]', '{"verb":"cry","noun":"cry"}', NULL, 1, 848, NULL),
